import {money,escapeHTML as h,retailPrice,effectiveOffer,formatSize,filterProducts,facetOptions,cartTotals,parseFilters,serializeFilters,fitmentMessage} from './domain.js';

const $=(s,root=document)=>root.querySelector(s);
const products=window.IMKONEX_DATA.products;
const validIds=new Set(products.map(p=>p.id));
const icons={
 heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',
 compare:'M5 20V10M12 20V4M19 20v-7',bag:'M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2',
 pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
 chevron:'m6 9 6 6 6-6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
 arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',
 check:'m5 12 4 4L19 6',info:'M12 11v6M12 7v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',
 snow:'M12 2v20M3 7l18 10M3 17 21 7M8 4l4 3 4-3M8 20l4-3 4 3',
 truck:'M1 5h13v12H1V5Zm13 4h4l4 5v3h-8M7 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',
 filter:'M4 7h16M4 17h16M8 4v6m8 4v6',car:'m3 10 2-6h14l2 6M2 10h20v9H2v-9Zm3 9v3m14-3v3M5 14h3m8 0h3',
 wheel:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 2v7m0 6v7M2 12h7m6 0h7M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0Z',
 trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6'
};
function icon(name){return `<svg class="icon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;}
function load(key,fallback){try{return JSON.parse(localStorage.getItem('imx:'+key))??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem('imx:'+key,JSON.stringify(value));}catch{toast('Браузер не разрешил сохранение. Данные останутся до закрытия страницы.');}}
function loadIds(key){const v=load(key,[]);return Array.isArray(v)?[...new Set(v.filter(id=>validIds.has(id)))]:[];}
let favorites=loadIds('favorites'),compare=loadIds('compare').slice(0,4);
const loadedCart=load('cart',[]);
let cart=Array.isArray(loadedCart)?loadedCart.filter(l=>l&&validIds.has(l.id)&&Number.isInteger(l.quantity)&&l.quantity>0&&l.quantity<=20):[];
let city=load('city','Челябинск');if(!['Челябинск','Екатеринбург','Москва','Санкт-Петербург'].includes(city))city='Челябинск';
let filters=parseFilters(location.hash.split('?')[1]||''),page=1,managerTab='overview',onlyDifferent=false;
let toastTimer;
const main=$('#main'),dialog=$('#dialog');
const seasonNames={summer:'Летние',winter:'Зимние',allseason:'Всесезонные'};
const checked=v=>v?' checked':'';
const selected=(a,b)=>String(a)===String(b)?' selected':'';
const product=id=>products.find(p=>p.id===id);
const assetUrl=path=>window.IMKONEX_IMAGE_MAP?.[path]||'./'+path;
const currentRoute=()=>location.hash.slice(1).split('?')[0]||'catalog';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function updateCounts(){for(const [key,count] of [['favorites',favorites.length],['compare',compare.length],['cart',cart.reduce((s,l)=>s+l.quantity,0)]]){const el=$(`#${key}-count`);el.textContent=count;el.hidden=!count;}$('#city-label').textContent=city;}
function closeDialog(){dialog.close();}
function showDialog(title,html){$('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${h(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body">${html}</div>`;dialog.showModal();}
function empty(title,description,action='В каталог'){return `<div class="empty-state">${icon('wheel')}<h2>${h(title)}</h2><p>${h(description)}</p><a class="btn btn-primary" href="#catalog">${h(action)} ${icon('arrow')}</a></div>`;}
function heading(title,note=''){return `<div class="breadcrumb"><a href="#catalog">Главная</a><span>/</span><span>${h(title)}</span></div><div class="page-heading"><h1>${h(title)}</h1>${note?`<p class="heading-note">${h(note)}</p>`:''}</div>`;}
function optionField(key,label,all='Любой',options=null){const values=options||facetOptions(products,filters,key);return `<label class="field"><span>${label}</span><select name="${key}" data-filter="${key}"><option value="">${all}</option>${values.map(v=>`<option value="${h(v)}"${selected(filters[key],v)}>${h(v)}</option>`).join('')}</select></label>`;}
function checkbox(key,label,disabled=false){return `<label class="check-row"><input type="checkbox" data-filter="${key}"${checked(filters[key])}${disabled?' disabled':''}><span>${h(label)}</span></label>`;}
function selector(){const tire=filters.kind==='tires';return `<section class="selector" aria-label="Подбор по параметрам"><div class="selector-top"><div class="category-tabs" role="group" aria-label="Категория"><button class="category-tab ${tire?'active':''}" data-action="category" data-kind="tires" aria-pressed="${tire}">${icon('wheel')} Шины</button><button class="category-tab ${!tire?'active':''}" data-action="category" data-kind="wheels" aria-pressed="${!tire}">${icon('wheel')} Диски</button></div><div class="selection-mode"><span>По размеру</span><a href="#garage">Для моего автомобиля ${icon('arrow')}</a></div></div><div class="selector-fields">${tire?optionField('width','Ширина, мм','Любая')+optionField('profile','Профиль, %','Любой')+optionField('diameter','Диаметр, дюймы','Любой'):optionField('diameter','Диаметр, дюймы','Любой')+optionField('wheelWidth','Ширина, J','Любая')+optionField('pcd','Крепёж, PCD','Любой')}<button class="btn btn-primary" data-action="show-results">Показать ${icon('arrow')}</button></div></section>`;}
function sidebar(){const brands=facetOptions(products,filters,'brands');return `<aside class="filters sidebar" id="filters" aria-label="Фильтры"><div class="filter-heading"><h2>Фильтры</h2><button class="text-link" data-action="reset">Сбросить</button><button class="icon-btn filter-close" data-action="close-filters" aria-label="Закрыть фильтры">${icon('close')}</button></div>${filters.kind==='tires'?`<section class="filter-section"><h3>Сезон</h3><div class="season-pills">${[['','Все'],['summer','Лето'],['winter','Зима']].map(([s,l])=>`<button class="season-btn ${filters.season===s?'active':''}" data-action="season" data-value="${s}" aria-pressed="${filters.season===s}">${s?icon(s==='summer'?'sun':'snow'):''}${l}</button>`).join('')}</div></section>`:`<section class="filter-section"><h3>Параметры диска</h3>${optionField('et','Вылет ET, мм')}${optionField('dia','Отверстие DIA, мм')}</section>`}<section class="filter-section"><h3>Производитель</h3>${brands.map(b=>`<label class="check-row"><input type="checkbox" data-brand="${h(b)}"${checked(filters.brands.includes(b))}><span>${h(b)}</span><small>${filterProducts(products,{...filters,brands:[b]}).length}</small></label>`).join('')}</section><section class="filter-section"><h3>Цена за штуку, ₽</h3><div class="price-inputs"><input aria-label="Минимальная цена" data-filter="min" inputmode="numeric" type="number" min="0" placeholder="От" value="${h(filters.min)}"><span>—</span><input aria-label="Максимальная цена" data-filter="max" inputmode="numeric" type="number" min="0" placeholder="До" value="${h(filters.max)}"></div></section><section class="filter-section"><h3>Наличие и срок</h3>${checkbox('inSet','Есть комплект из 4 шт.')}${checkbox('fast','Доставка до 3 дней')}</section>${filters.kind==='tires'?`<section class="filter-section"><h3>Дополнительно</h3>${checkbox('xl','Усиленные XL')}${checkbox('runflat','RunFlat')}${checkbox('studded','С шипами')}</section>`:''}<div class="side-help">${icon('car')}<h3>Не знаете свой размер?</h3><p>Сохраните параметры автомобиля и возвращайтесь к подбору.</p><a href="#garage">В мой гараж ${icon('arrow')}</a></div></aside>`;}
function productCard(p){const offer=effectiveOffer(p,filters.inSet?4:1),set=effectiveOffer(p,4),fav=favorites.includes(p.id),cmp=compare.includes(p.id);return `<article class="product-card"><div class="product-image"><span class="product-tag">${icon(p.kind==='wheels'?'wheel':p.season==='winter'?'snow':'sun')} ${p.kind==='wheels'?'Литой диск':seasonNames[p.season]}</span><div class="product-actions"><button class="icon-btn ${fav?'selected':''}" data-action="favorite" data-id="${p.id}" aria-label="${fav?'Удалить из':'Добавить в'} избранное ${h(p.brand+' '+p.model)}" aria-pressed="${fav}">${icon('heart')}</button><button class="icon-btn ${cmp?'selected':''}" data-action="compare" data-id="${p.id}" aria-label="${cmp?'Удалить из':'Добавить в'} сравнение ${h(p.model)}" aria-pressed="${cmp}">${icon('compare')}</button></div><button class="product-open product-visual" data-action="detail" data-id="${p.id}" aria-label="Подробнее: ${h(p.brand+' '+p.model+' '+formatSize(p))}"><img src="${h(assetUrl(p.image))}" alt="${h(p.brand+' '+p.model)}" width="400" height="400" loading="lazy"></button></div><div class="product-info"><p class="product-brand">${h(p.brand)}</p><h3><button class="product-title" data-action="detail" data-id="${p.id}">${h(p.model)}</button></h3><p class="product-size">${h(formatSize(p))}</p><p class="product-meta">${p.kind==='tires'?`${h(p.loadIndex+p.speedIndex)}${p.xl?' · XL':''} · ${p.studded?'Шипованные':'Без шипов'}`:`ET ${p.et} · DIA ${p.dia} · ${h(p.color)}`}</p><div class="stock-row ${offer?'':'no-stock'}">${icon(offer?'check':'info')}<span>${offer?`${offer.stock} шт. · ${offer.days}–${offer.days+1} дн.`:'Нет в демо-наличии'}</span><span class="muted">демо</span></div><div class="product-price unit-price product-pricing">${offer?`<strong>${money(offer.price)}</strong><span>/ шт.</span>`:'<strong>По запросу</strong>'}</div><div class="card-bottom"><div class="set-price">${set?`4 шт. <b>${money(set.price*4)}</b>`:'Комплект недоступен'}</div><button class="btn btn-primary btn-small" data-action="add" data-id="${p.id}" data-quantity="${set?4:1}" ${offer?'':'disabled'} aria-label="Добавить ${set?'4 штуки':'1 штуку'} ${h(p.model)}">${icon('plus')} ${set?'4 шт.':'1 шт.'}</button></div></div></article>`;}
function activeChips(){const names={width:'Ширина',profile:'Профиль',diameter:'Диаметр',pcd:'PCD',wheelWidth:'Ширина J',et:'ET',dia:'DIA',season:'Сезон',q:'Поиск',min:'Цена от',max:'Цена до',inSet:'Комплект 4 шт.',fast:'До 3 дней',xl:'XL',runflat:'RunFlat',studded:'Шипы'};return Object.entries(names).filter(([k])=>filters[k]).map(([k,l])=>`<button class="filter-chip active-filter" data-action="remove-filter" data-key="${k}">${h(typeof filters[k]==='boolean'?l:`${l}: ${seasonNames[filters[k]]||filters[k]}`)} ${icon('close')}</button>`).concat(filters.brands.map(b=>`<button class="filter-chip active-filter" data-action="remove-brand" data-brand="${h(b)}">${h(b)} ${icon('close')}</button>`)).join('');}
function renderCatalog(favoriteOnly=false){const found=filterProducts(products,{...filters,onlyFavorites:favoriteOnly},{favorites}),pages=Math.max(1,Math.ceil(found.length/12));page=Math.min(page,pages);const pageProducts=found.slice((page-1)*12,page*12);main.innerHTML=heading(favoriteOnly?'Избранное':'Шины и диски',favoriteOnly?'Ваши сохранённые варианты':'Найдите свой размер. Сравните. Соберите комплект.')+selector()+`<div class="catalog-layout">${sidebar()}<section class="catalog-results" aria-label="Товары"><div class="catalog-toolbar"><div><h2>${filters.kind==='tires'?'Автомобильные шины':'Легкосплавные диски'} <span class="results-count" aria-live="polite">${found.length}</span></h2></div><button class="btn btn-ghost btn-small mobile-filter-btn" data-action="open-filters">${icon('filter')} Фильтры</button><label class="sort-label"><span>Сначала</span><select class="sort-select" data-filter="sort" aria-label="Сортировка">${[['recommended','Рекомендуемые'],['price-up','Дешевле'],['price-down','Дороже'],['delivery','Быстрее доставка']].map(([v,t])=>`<option value="${v}"${selected(filters.sort,v)}>${t}</option>`).join('')}</select></label></div><form id="search-form" class="search-wrap">${icon('search')}<input type="search" name="q" aria-label="Поиск по модели или размеру" placeholder="Бренд, модель или размер — например, 225/45 R18" value="${h(filters.q)}"><button class="text-link" type="submit">Найти</button></form><div class="active-filters">${activeChips()}</div>${found.length?`<div class="product-grid">${pageProducts.map(productCard).join('')}</div><nav class="pagination" aria-label="Страницы каталога">${Array.from({length:pages},(_,i)=>`<button class="${page===i+1?'active':''}" data-action="page" data-page="${i+1}" aria-label="Страница ${i+1}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<span>${(page-1)*12+1}–${Math.min(page*12,found.length)} из ${found.length}</span></nav>`:empty(favoriteOnly?'Здесь пока нет подходящих избранных':'Ничего не найдено','Попробуйте изменить размер или сбросить фильтры.')}<p class="catalog-footnote">Сроки показаны для демонстрационного расчёта. ${city!=='Челябинск'?'Доставка в выбранный город не рассчитана. ':''}Размеры и применимость требуют проверки.</p></section></div>`;}
function renderDetail(id){const p=product(id);if(!p)return;const o=effectiveOffer(p,4)||effectiveOffer(p);showDialog('Карточка товара',`<div class="detail-grid"><div class="detail-image"><img src="${h(assetUrl(p.image))}" alt="${h(p.brand+' '+p.model)}" width="500" height="500"></div><div><span class="pill">Демонстрационный артикул</span><p class="product-brand">${h(p.brand)}</p><h2>${h(p.model)}</h2><p class="detail-size">${h(formatSize(p))}</p><p class="muted">${h(p.sku)}</p><div class="detail-price">${o?money(o.price)+' <small>/ шт.</small>':'Нет в наличии'}</div><p>${h(p.description)}</p><button class="btn btn-primary full" data-action="add" data-id="${p.id}" data-quantity="${effectiveOffer(p,4)?4:1}" ${o?'':'disabled'}>${icon('bag')} Добавить ${effectiveOffer(p,4)?'комплект 4 шт.':'1 шт.'}</button><p class="form-hint">${fitmentMessage()}</p></div></div><div class="divider"></div><h3>Параметры примера</h3><dl class="spec-list">${specRows(p).map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(v)}</dd></div>`).join('')}</dl><h3>Предложения демо-складов</h3>${p.offers.length?p.offers.map(o=>`<div class="offer-row"><span>${h(o.warehouse)}<small>${o.stock} шт. · ${o.days}–${o.days+1} дн.</small></span><strong>${money(o.price)}</strong></div>`).join(''):'<p class="muted">Нет предложений</p>'}<p class="form-hint">Цены и остатки условные. Для комплекта выбирается склад, на котором есть всё необходимое количество.</p>`);}
function specRows(p){return [['Производитель',p.brand],['Модель',p.model],['Размер',formatSize(p)],...(p.kind==='tires'?[['Сезон',seasonNames[p.season]],['Индекс нагрузки / скорости',p.loadIndex+p.speedIndex],['Шипы',p.studded?'Да':'Нет'],['RunFlat',p.runflat?'Да':'Нет'],['Усиление XL',p.xl?'Да':'Нет']]:[['PCD',p.pcd],['Вылет ET',p.et+' мм'],['Центральное отверстие',p.dia+' мм'],['Цвет',p.color],['Тип','Литой']]),['Применимость','Не подтверждена']];}
function renderCompare(){const ps=compare.map(product).filter(Boolean);main.innerHTML=heading('Сравнение',`${ps.length} из 4 товаров`)+(ps.length?`<div class="comparison-toolbar"><label class="check-row"><input type="checkbox" id="differences"${checked(onlyDifferent)}>Только различия</label><button class="text-link" data-action="clear-compare">Очистить сравнение</button></div><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th scope="col">Характеристики</th>${ps.map(p=>`<th scope="col"><div class="compare-head"><button class="icon-btn" data-action="compare" data-id="${p.id}" aria-label="Убрать ${h(p.model)}">${icon('close')}</button><img src="${h(assetUrl(p.image))}" alt="${h(p.model)}" width="180" height="180"><span>${h(p.brand)}</span><h2>${h(p.model)}</h2><p>${h(formatSize(p))}</p><strong>${effectiveOffer(p)?money(effectiveOffer(p).price):'Нет в наличии'}</strong><button class="btn btn-primary btn-small" data-action="add" data-id="${p.id}" data-quantity="4" ${effectiveOffer(p,4)?'':'disabled'}>4 шт. в корзину</button></div></th>`).join('')}</tr></thead><tbody>${specRows(ps[0]).map(([label],index)=>{const vs=ps.map(p=>specRows(p)[index]?.[1]??'—'),different=new Set(vs.map(String)).size>1;return onlyDifferent&&!different?'':`<tr class="${different?'different':''}"><th scope="row">${h(label)}</th>${vs.map(v=>`<td>${h(v)}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div><p class="form-hint">Сравнение относится к тестовым данным. Фактические параметры нужно проверить по артикулам поставщика.</p>`:empty('Добавьте товары для сравнения','Нажмите значок сравнения на карточке. Можно сравнить до четырёх товаров одной категории.'));}
function renderCart(){const t=cartTotals(cart,products);main.innerHTML=heading('Ваш комплект',t.items.length?`${t.items.length} позиций в корзине`:'')+(t.items.length?`<div class="cart-layout"><section aria-label="Товары в корзине"><div class="cart-top"><a href="#catalog" class="text-link">← Продолжить подбор</a><button class="text-link" data-action="clear-cart">Очистить корзину</button></div>${t.items.map(l=>`<article class="cart-row"><button class="cart-image" data-action="detail" data-id="${l.id}"><img src="${h(assetUrl(l.product.image))}" alt="${h(l.product.model)}" width="110" height="120"></button><div class="cart-info"><p class="product-brand">${h(l.product.brand)}</p><h2>${h(l.product.model)}</h2><p>${h(formatSize(l.product))}</p><p class="muted">${l.unavailable?'Нет нужного количества на одном складе':`${h(l.offer.warehouse)} · ${l.offer.days}–${l.offer.days+1} дн.`}</p><div class="quantity-control"><button data-action="quantity" data-id="${l.id}" data-delta="-1" aria-label="Уменьшить количество" ${l.quantity<=1?'disabled':''}>${icon('minus')}</button><span aria-label="Количество">${l.quantity}</span><button data-action="quantity" data-id="${l.id}" data-delta="1" aria-label="Увеличить количество" ${l.quantity>=20?'disabled':''}>${icon('plus')}</button></div></div><div class="cart-row-total"><strong>${l.unavailable?'Недоступно':money(l.subtotal)}</strong><small>${l.unavailable?'':money(l.offer.price)+' / шт.'}</small><button class="icon-btn" data-action="remove-cart" data-id="${l.id}" aria-label="Удалить ${h(l.product.model)}">${icon('trash')}</button></div></article>`).join('')}<div class="wide-callout">${icon('shield')}<div><h3>Проверьте совместимость перед заказом</h3><p>Совпадение диаметра не подтверждает применимость. Для дисков важны также ширина, PCD, ET, DIA и зазор тормозных механизмов.</p></div></div></section><aside class="summary-panel"><h2>Расчёт комплекта</h2><div class="summary-line"><span>Товары · ${t.count} шт.</span><span>${money(t.total)}</span></div><div class="summary-line"><span>Доставка</span><span>Не рассчитана</span></div><div class="summary-total"><span>Итого без доставки</span><strong>${money(t.total)}</strong></div><button class="btn btn-primary full" data-action="quote" ${t.issues.length?'disabled':''}>Сохранить тестовую заявку ${icon('arrow')}</button><button class="btn btn-ghost full" data-action="download-quote" ${t.issues.length?'disabled':''}>${icon('download')} Скачать расчёт</button><p class="form-hint">Заявка сохраняется только в этом браузере. Она не отправляется менеджеру или поставщику. Оплата отключена.</p>${t.issues.length?'<p class="error-text">Уменьшите количество недоступных позиций.</p>':''}</aside></div>`:empty('Корзина пока пуста','Подберите размер и добавьте комплект из каталога.'));}
function garageData(){const g=load('garage',{});return g&&typeof g==='object'&&!Array.isArray(g)?g:{};}
function renderGarage(){const g=garageData();main.innerHTML=heading('Мой автомобиль','Сохраните размер для следующего подбора')+`<div class="garage-layout"><section class="panel"><h2>Параметры вашего автомобиля</h2><p class="muted">Укажите известные параметры из руководства автомобиля или маркировки установленных колёс.</p><form id="garage-form"><div class="form-grid"><label class="field"><span>Марка</span><input name="brand" maxlength="60" list="car-brands" placeholder="Например, Toyota" value="${h(g.brand)}" required><datalist id="car-brands">${['Toyota','BMW','Mercedes-Benz','Volkswagen','Kia','Hyundai','Lexus','Audi','Geely','Chery','Lada'].map(v=>`<option value="${v}"></option>`).join('')}</datalist></label><label class="field"><span>Модель</span><input name="model" maxlength="80" placeholder="Например, Camry" value="${h(g.model)}" required></label><label class="field"><span>Год выпуска</span><input name="year" type="number" min="1950" max="2030" placeholder="2022" value="${h(g.year)}" required></label><label class="field"><span>Ширина шины, мм</span><input name="width" type="number" min="125" max="405" value="${h(g.width)}" placeholder="225" required></label><label class="field"><span>Профиль, %</span><input name="profile" type="number" min="20" max="90" value="${h(g.profile)}" placeholder="45" required></label><label class="field"><span>Диаметр, дюймы</span><input name="diameter" type="number" min="12" max="26" value="${h(g.diameter)}" placeholder="18" required></label></div><p class="form-hint">Это сохранение введённого вами размера. Автоматическая проверка по модели автомобиля появится после подключения подтверждённой базы применимости.</p><div class="form-actions"><button type="submit" class="btn btn-primary">Сохранить и подобрать ${icon('arrow')}</button>${g.brand?'<button type="button" class="text-link" data-action="clear-garage">Удалить автомобиль</button>':''}</div></form></section><aside class="panel garage-help">${icon('car')}<h2>Где найти размер?</h2><p><b>225/45 R18</b> — пример маркировки на боковине шины.</p><p>Ширина — 225 мм, высота профиля — 45% ширины, посадочный диаметр — 18 дюймов.</p><p>Допустимые размеры и индексы указаны в документации автомобиля. Передняя и задняя оси могут отличаться.</p><a class="text-link" href="#guide">Разобраться в параметрах ${icon('arrow')}</a></aside></div>`;}
function renderGuide(){main.innerHTML=heading('Как выбрать колёса','Понятные параметры для уверенного подбора')+`<div class="page-cards"><article class="content-card">${icon('wheel')}<h2>Размер шины</h2><h3>225 / 45 R18</h3><p><b>225</b> — ширина в миллиметрах. <b>45</b> — отношение высоты профиля к ширине в процентах. <b>R</b> — радиальная конструкция. <b>18</b> — посадочный диаметр в дюймах.</p><p>Индексы нагрузки и скорости выбирают с учётом требований автомобиля, а не только размера.</p></article><article class="content-card">${icon('car')}<h2>Параметры диска</h2><h3>8J × 18 · 5×112 · ET35</h3><p><b>8</b> — ширина обода в дюймах; <b>J</b> — обозначение профиля закраины. <b>5×112</b> — пять крепёжных отверстий на окружности диаметром 112 мм.</p><p><b>ET</b> — вылет диска, <b>DIA</b> — диаметр центрального отверстия. Также проверяют крепёж, нагрузку и зазоры.</p></article><article class="content-card">${icon('truck')}<h2>Цена комплекта</h2><h3>Один склад · нужное количество</h3><p>Каталог выбирает предложение с достаточным остатком на одном складе. Если локально есть две штуки, комплект из четырёх рассчитывается по другому подходящему предложению.</p><p>Итог в демоверсии не включает доставку, шиномонтаж, крепёж и датчики давления.</p></article></div><div class="wide-callout">${icon('info')}<div><h2>Финальная проверка — по конкретному автомобилю</h2><p>Совпадение одного параметра не гарантирует совместимость. Наш демонстрационный гараж запоминает введённый размер, но не подтверждает применимость.</p><a class="btn btn-primary" href="#garage">Сохранить свой размер ${icon('arrow')}</a></div></div>`;}
function getRequests(){const r=load('requests',[]);return Array.isArray(r)?r.filter(x=>x&&typeof x.id==='string'&&Number.isFinite(x.total)).slice(0,100):[];}
function renderManager(){const requests=getRequests(),total=requests.reduce((s,r)=>s+r.total,0);const labels=[['overview','Обзор'],['requests','Тестовые заявки'],['pricing','Расчёт наценки'],['integration','Интеграции']];let content='';
 if(managerTab==='overview')content=`<h2>Состояние демонстрации</h2><div class="metric-grid"><div><span>Вариантов в каталоге</span><strong>${products.length}</strong><small>36 шин · 36 дисков</small></div><div><span>Заявок в браузере</span><strong>${requests.length}</strong><small>Не отправлены поставщику</small></div><div><span>Тестовая сумма заявок</span><strong>${money(total)}</strong><small>Без оплаты и доставки</small></div></div><section class="panel"><h3>Готово для первого этапа</h3><ul class="simple-list"><li>Каталог с фильтрами и параметрами в адресе</li><li>Избранное, сравнение, комплект и расчёт</li><li>Сохранение известного размера автомобиля</li><li>Статическая публикация на бесплатном Render</li></ul><p class="form-hint">Этот кабинет публичный и содержит только демонстрационные данные. Закупочные цены и пароли здесь не хранятся.</p></section>`;
 if(managerTab==='requests')content=`<h2>Тестовые заявки</h2><p class="muted">Только записи, созданные в этом браузере. Контактные данные не собираются.</p>${requests.length?`<div class="comparison-scroll"><table class="manager-table"><thead><tr><th>Номер</th><th>Создана</th><th>Позиций</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>${requests.map(r=>`<tr><td>${h(r.id)}</td><td>${h(new Date(r.createdAt).toLocaleDateString('ru-RU'))}</td><td>${r.lines?.length||0}</td><td>${money(r.total)}</td><td><span class="status-label">Локальная демо</span></td></tr>`).join('')}</tbody></table></div><button class="text-link" data-action="clear-requests">Удалить тестовые заявки</button>`:empty('Тестовых заявок ещё нет','Добавьте товары в корзину и сохраните тестовую заявку.')}`;
 if(managerTab==='pricing'){const stored=load('pricing',{percent:18,minimum:700});const rule=stored&&typeof stored==='object'?stored:{percent:18,minimum:700};content=`<h2>Калькулятор наценки</h2><p class="muted">Проверка правила на введённой цене. Каталог от этого расчёта не изменяется.</p><form class="panel" id="pricing-form"><div class="form-grid"><label class="field"><span>Условная закупочная цена, ₽</span><input name="cost" type="number" min="1" max="10000000" value="10000" required></label><label class="field"><span>Наценка, %</span><input name="percent" type="number" min="0" max="1000" step="0.1" value="${h(rule.percent??18)}" required></label><label class="field"><span>Минимальная наценка, ₽</span><input name="minimum" type="number" min="0" max="1000000" value="${h(rule.minimum??700)}" required></label></div><p class="form-hint">Цена = закупка + большее из процентной и минимальной наценки. Округление вверх до 10 ₽.</p><button class="btn btn-primary" type="submit">Рассчитать</button><div class="price-preview" id="price-preview" aria-live="polite"></div></form>`;}
 if(managerTab==='integration')content=`<h2>Подключение данных</h2><div class="integration-box"><div><h3>4tochki B2B</h3><span class="status-label off">Не подключено</span></div><p>Подготовлена серверная диагностика SOAP. Потребуются действующие учётные данные, проверка схемы методов и сопоставление полей.</p><p class="form-hint">Пароли вводятся только в настройках сервера. Создание заказа у поставщика отключено.</p></div><div class="integration-box"><div><h3>API IMKONEX</h3><span class="status-label off" id="api-status">${window.IMKONEX_CONFIG.apiBase?'Не проверено':'Адрес не настроен'}</span></div><p>Демо-каталог работает независимо от API. После настройки адреса можно проверить доступность сервера.</p><button class="btn btn-ghost btn-small" data-action="check-api" ${window.IMKONEX_CONFIG.apiBase?'':'disabled'}>Проверить соединение</button></div><div class="integration-box"><div><h3>Применимость к автомобилям</h3><span class="status-label off">База не подключена</span></div><p>Сохранённый в гараже размер не означает подтверждённой совместимости.</p></div>`;
 main.innerHTML=heading('Кабинет менеджера','Демонстрация · данные на этом устройстве')+`<div class="manager-layout"><nav class="manager-menu" aria-label="Разделы кабинета">${labels.map(([v,l])=>`<button class="${managerTab===v?'active':''}" data-action="manager-tab" data-value="${v}">${l}</button>`).join('')}<a href="#catalog">← Вернуться в каталог</a></nav><section class="manager-content">${content}</section></div>`;}
function persistCart(){save('cart',cart);updateCounts();}
function addToCart(id,amount){const p=product(id);if(!p)return;const line=cart.find(l=>l.id===id),quantity=(line?.quantity||0)+amount;if(quantity>20||!effectiveOffer(p,quantity)){toast('На одном складе нет нужного количества. Проверьте корзину.');return;}if(line)line.quantity=quantity;else cart.push({id,quantity});persistCart();toast(`Добавлено ${amount} шт. — ${p.brand} ${p.model}`);}
function toggleFavorite(id){if(!validIds.has(id))return;favorites=favorites.includes(id)?favorites.filter(v=>v!==id):[...favorites,id];save('favorites',favorites);render();}
function toggleCompare(id){const p=product(id);if(!p)return;if(compare.includes(id))compare=compare.filter(v=>v!==id);else{if(compare.length>=4){toast('Можно сравнить до 4 товаров. Уберите один из сравнения.');return;}if(compare.length&&product(compare[0]).kind!==p.kind){toast('Сравнивайте товары одной категории. Сначала очистите сравнение.');return;}compare.push(id);}save('compare',compare);render();}
function setFilter(key,value){filters[key]=value;page=1;syncFilters();}
function syncFilters(){const route=currentRoute()==='favorites'?'favorites':'catalog';history.replaceState(null,'',`#${route}?${serializeFilters(filters)}`);render();}
function quoteData(){const t=cartTotals(cart,products);return {id:`DEMO-${Date.now().toString(36).toUpperCase()}`,createdAt:new Date().toISOString(),mode:'demo',city,total:t.total,deliveryIncluded:false,fitmentConfirmed:false,lines:t.items.map(l=>({id:l.id,name:`${l.product.brand} ${l.product.model}`,size:formatSize(l.product),quantity:l.quantity,price:l.offer?.price,warehouse:l.offer?.warehouse})),notice:'Тестовый расчёт. Не является заказом. Все параметры и суммы условные.'};}
function downloadQuote(){if(cartTotals(cart,products).issues.length)return;const data=quoteData(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`imkonex-${data.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Тестовый расчёт сохранён в JSON.');}
function render(){const route=currentRoute();if(dialog.open)dialog.close();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});updateCounts();if(route==='cart')renderCart();else if(route==='compare')renderCompare();else if(route==='garage')renderGarage();else if(route==='guide')renderGuide();else if(route==='manager')renderManager();else renderCatalog(route==='favorites');document.title=`${({cart:'Корзина',compare:'Сравнение',garage:'Мой автомобиль',guide:'Как выбрать',manager:'Демо-кабинет',favorites:'Избранное'})[route]||'Шины и диски'} — IMKONEX CARS`;}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const {action,id,value}=button.dataset;
 if(action==='favorite')toggleFavorite(id);
 if(action==='compare')toggleCompare(id);
 if(action==='detail')renderDetail(id);
 if(action==='close-dialog')closeDialog();
 if(action==='add')addToCart(id,Number(button.dataset.quantity));
 if(action==='category'){filters=parseFilters(`kind=${button.dataset.kind}`);page=1;syncFilters();}
 if(action==='season')setFilter('season',value);
 if(action==='reset'){filters=parseFilters(`kind=${filters.kind}`);page=1;syncFilters();}
 if(action==='remove-filter')setFilter(button.dataset.key,'');
 if(action==='remove-brand'){filters.brands=filters.brands.filter(b=>b!==button.dataset.brand);syncFilters();}
 if(action==='show-results'){$('.catalog-results')?.scrollIntoView({behavior:'smooth',block:'start'});}
 if(action==='page'){page=Number(button.dataset.page);render();$('.catalog-toolbar')?.scrollIntoView({behavior:'smooth',block:'start'});}
 if(action==='open-filters'){$('#filters').classList.add('open');$('.filter-close').focus();}
 if(action==='close-filters'){$('#filters').classList.remove('open');$('.mobile-filter-btn').focus();}
 if(action==='clear-compare'){compare=[];save('compare',compare);render();}
 if(action==='clear-cart'){cart=[];persistCart();render();}
 if(action==='remove-cart'){cart=cart.filter(l=>l.id!==id);persistCart();render();}
 if(action==='quantity'){const line=cart.find(l=>l.id===id);if(!line)return;const n=line.quantity+Number(button.dataset.delta);if(n<1||n>20)return;if(!effectiveOffer(product(id),n)){toast('На одном складе нет нужного количества.');return;}line.quantity=n;persistCart();render();}
 if(action==='clear-garage'){save('garage',{});render();}
 if(action==='manager-tab'){managerTab=value;render();}
 if(action==='clear-requests'){save('requests',[]);render();}
 if(action==='download-quote')downloadQuote();
 if(action==='quote'){if(!cart.length||cartTotals(cart,products).issues.length)return;const q=quoteData();save('requests',[q,...getRequests()].slice(0,100));showDialog('Тестовая заявка сохранена',`<div class="empty-state">${icon('check')}<h2>${h(q.id)}</h2><p>Расчёт на ${money(q.total)} доступен в демо-кабинете на этом устройстве. Менеджеру и поставщику ничего не отправлено.</p><a class="btn btn-primary" href="#manager">Открыть кабинет ${icon('arrow')}</a></div>`);managerTab='requests';}
 if(action==='city'){city=value;save('city',city);closeDialog();render();toast(city==='Челябинск'?'Город сохранён':'Город сохранён. Сроки доставки в этот город пока не рассчитаны.');}
 if(action==='check-api'){const status=$('#api-status');status.textContent='Проверяем…';button.disabled=true;try{const r=await fetch(window.IMKONEX_CONFIG.apiBase.replace(/\/$/,'')+'/health',{signal:AbortSignal.timeout(8000)});if(!r.ok)throw new Error();const d=await r.json();status.textContent=d.status==='ok'?`Доступен · ${d.mode==='demo'?'демо':'сервер'}`:'Нужна проверка';}catch{status.textContent='Не удалось подключиться';}finally{button.disabled=false;}}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){const wasOpen=$('#filters')?.classList.contains('open');setFilter(el.dataset.filter,el.type==='checkbox'?el.checked:el.value);if(wasOpen)$('#filters')?.classList.add('open');}if(el.dataset.brand){filters.brands=el.checked?[...new Set([...filters.brands,el.dataset.brand])]:filters.brands.filter(b=>b!==el.dataset.brand);syncFilters();}if(el.id==='differences'){onlyDifferent=el.checked;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();setFilter('q',new FormData(e.target).get('q').trim());}if(e.target.id==='garage-form'){e.preventDefault();const g=Object.fromEntries(new FormData(e.target));save('garage',g);filters=parseFilters('');Object.assign(filters,{width:g.width,profile:g.profile,diameter:g.diameter});location.hash='catalog?'+serializeFilters(filters);toast('Размер сохранён. Применимость не подтверждена.');}if(e.target.id==='pricing-form'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const price=retailPrice(f.cost,f.percent,f.minimum);$('#price-preview').innerHTML=`<span>Расчётная розничная цена</span><strong>${money(price)}</strong><small>Наценка ${money(price-Number(f.cost))} за штуку</small>`;save('pricing',{percent:Number(f.percent),minimum:Number(f.minimum)});}catch{$('#price-preview').textContent='Проверьте значения.';}}});
$('#city-button').addEventListener('click',()=>showDialog('Ваш город',`<p class="muted">В демоверсии сроки рассчитаны условно для Челябинска. Для других городов доставка требует отдельного расчёта.</p><div class="city-list">${['Челябинск','Екатеринбург','Москва','Санкт-Петербург'].map(c=>`<button data-action="city" data-value="${c}" class="${city===c?'active':''}">${icon('pin')}${c}${city===c?icon('check'):''}</button>`).join('')}</div>`));
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#filters')?.classList.remove('open');});
window.addEventListener('hashchange',()=>{if(['catalog','favorites'].includes(currentRoute())){filters=parseFilters(location.hash.split('?')[1]||'');page=1;}render();window.scrollTo({top:0});});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
render();
